        if (bg) st += 'background:' + bg + ';';
        if (run.a & A_BOLD) st += 'font-weight:700;';
        if (run.a & A_DIM) st += 'opacity:.6;';
        if (run.a & A_ITALIC) st += 'font-style:italic;';
        if (run.a & A_UNDER) st += 'text-decoration:underline;';
